// 6天分批配置
const TOTAL_PAGES = 111;
const DAYS = 6;
const PAGES_PER_DAY = 19;

const CONFIG = {
  accountName: '饼干哥哥AGI',
  apiKey: 'JZLdc9670be1403c05c',
  baseUrl: 'https://www.dajiala.com/fbmain/monitor/v3/post_history',
  pagesPerDay: PAGES_PER_DAY,
  delayMs: 3000
};

const FEISHU_CONFIG = {
  appId: 'cli_a907365bcefbdbd2',
  appSecret: 'UOnIdOt4xWAgLrzVJUmrQbAOu8Icetjv'
};

return [{
  json: {
    config: CONFIG,
    feishu: FEISHU_CONFIG,
    currentPage: 1,
    startPage: 1,
    endPage: PAGES_PER_DAY,
    totalPages: TOTAL_PAGES,
    allArticles: [],
    totalCost: 0,
    dayInfo: {
      currentDay: 1,
      totalDays: DAYS
    }
  }
}];

const response = $input.first().json;
const endPage = $input.first().json.endPage;

if (response.code !== 0) {
  if (response.code === 110 || response.code === 115) {
    return [{json: {...$input.first().json, hasMore: false}}];
  }
  throw new Error(`API错误: ${response.msg}`);
}

const articles = response.data || [];
const currentPage = $input.first().json.currentPage;
const allArticles = $input.first().json.allArticles || [];

const existingIds = new Set(allArticles.map(a => a.appmsgid));
const newArticles = articles.filter(a => !existingIds.has(a.appmsgid));
allArticles.push(...newArticles);

const hasMore = currentPage < endPage;
const todayProgress = currentPage - $input.first().json.startPage + 1;
const todayTotal = endPage - $input.first().json.startPage + 1;

console.log(`第 ${currentPage} 页: ${newArticles.length} 篇新文章`);

return [{
  json: {
    ...$input.first().json,
    articles: newArticles,
    allArticles,
    hasMore,
    nextPage: currentPage + 1,
    remainMoney: response.remain_money,
    totalCost: ($input.first().json.totalCost || 0) + (response.cost_money || 0)
  }
}];

// 生成Markdown文件内容
const data = $input.first().json;
const articles = data.allArticles;

let markdown = `# 📰 饼干哥哥AGI - 文章汇总\n\n`;
markdown += `## 📊 第${data.dayInfo.currentDay}天抓取报告\n\n`;
markdown += `- ⏰ 抓取时间: ${new Date().toLocaleString()}\n`;
markdown += `- 📄 页数: ${data.endPage - data.startPage + 1}页\n`;
markdown += `- 📰 文章数: ${articles.length}篇\n`;
markdown += `- 💰 费用: ${data.totalCost.toFixed(2)}元\n`;
markdown += `- 💳 余额: ${data.remainMoney}元\n\n`;
markdown += `---\n\n`;

// 按日期分组
const grouped = {};
articles.forEach(article => {
  const date = article.post_time_str.split(' ')[0];
  if (!grouped[date]) grouped[date] = [];
  grouped[date].push(article);
});

// 生成文章列表
Object.keys(grouped).sort((a, b) => new Date(b) - new Date(a)).forEach(date => {
  markdown += `### 📅 ${date}\n\n`;
  grouped[date].forEach((article, idx) => {
    markdown += `**${idx + 1}. ${article.title}**\n\n`;
    markdown += `- 📝 ${article.digest || '暂无摘要'}\n`;
    markdown += `- ⏰ ${article.post_time_str}\n`;
    markdown += `- 🔗 [阅读原文](${article.url})\n`;
    markdown += `- ✅ ${article.original === 1 ? '原创' : '转载'}\n\n`;
  });
});

const filename = `binggan_day${data.dayInfo.currentDay}_${Date.now()}.md`;

return [{
  json: {
    ...data,
    markdown,
    filename,
    articleCount: articles.length
  }
}];

